import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Design Mode","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/cursor/design-mode.md","filePath":"products/ai-coding/cursor/design-mode.md","lastUpdated":1787110548000}'),r={name:"products/ai-coding/cursor/design-mode.md"};function i(s,e,l,d,h,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="design-mode" tabindex="-1">Design Mode <a class="header-anchor" href="#design-mode" aria-label="Permalink to &quot;Design Mode&quot;">​</a></h1><p>Design Mode lets you <strong>direct agents with visual prompts</strong>. In the browser inside the <a href="https://cursor.com/docs/agent/agents-window" target="_blank" rel="noreferrer">Agents Window</a>, you click an element, draw on the page, or speak. Cursor captures the element plus a screenshot and edits the code while you move to the next change.</p><blockquote><p>Official: <a href="https://cursor.com/docs/agent/design-mode" target="_blank" rel="noreferrer">Design Mode</a>. Toggle: <strong><code>Cmd+Shift+D</code></strong>.</p><p>This is <strong>in-app UI direction</strong>, not a standalone design canvas. Closest cousin on this site: <a href="./../claude/claude-design.html">Claude Design</a>.</p></blockquote><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Cursor desktop, with the <strong>Agents Window</strong> browser open on a running app</li><li>A UI you can actually load in that browser (local dev server or preview)</li><li>A fast model that is strong at interface work — official recommendation: <strong><a href="https://cursor.com/blog/composer-2-5" target="_blank" rel="noreferrer">Composer 2.5</a></strong></li></ul><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>After this page you can:</p><ol><li>Open and close Design Mode without leaving the running app</li><li>Target one element, several elements, a drawn region, or a voice note</li><li>Know what the agent actually sees (identity + screenshot)</li><li>Queue the next visual edit before the first one finishes</li></ol><hr><h2 id="why-a-visual-prompt" tabindex="-1">Why a visual prompt <a class="header-anchor" href="#why-a-visual-prompt" aria-label="Permalink to &quot;Why a visual prompt&quot;">​</a></h2><p>UI work is spatial. A sentence like “make the hero less cramped” is weaker than: the selected node, the code behind it, the surrounding layout, and the page state you are looking at.</p><p>Click an element in the running app, prompt against that selection, and let the agent edit the source.</p><h2 id="open-design-mode" tabindex="-1">Open Design Mode <a class="header-anchor" href="#open-design-mode" aria-label="Permalink to &quot;Open Design Mode&quot;">​</a></h2><p>Design Mode lives in the <strong>browser inside the Agents Window</strong>.</p><ol><li>Open the Agents Window browser</li><li>Toggle Design Mode with <strong><code>Cmd+Shift+D</code></strong></li><li>Toggle it off with the same shortcut to return to normal browsing</li></ol><h2 id="ways-to-direct-the-agent" tabindex="-1">Ways to direct the agent <a class="header-anchor" href="#ways-to-direct-the-agent" aria-label="Permalink to &quot;Ways to direct the agent&quot;">​</a></h2><h3 id="select-an-element" tabindex="-1">Select an element <a class="header-anchor" href="#select-an-element" aria-label="Permalink to &quot;Select an element&quot;">​</a></h3><p>Click any element in the running product. The agent gets the element <strong>and</strong> its code, so you prompt against the thing you see.</p><h3 id="select-multiple-elements" tabindex="-1">Select multiple elements <a class="header-anchor" href="#select-multiple-elements" aria-label="Permalink to &quot;Select multiple elements&quot;">​</a></h3><p>Multi-select when the change is a <strong>relationship</strong>: make A match B, remove repeated content, or adjust a group together.</p><h3 id="draw-on-the-page" tabindex="-1">Draw on the page <a class="header-anchor" href="#draw-on-the-page" aria-label="Permalink to &quot;Draw on the page&quot;">​</a></h3><p>Circle a crowded section, box a region, or mark part of an animated page. The annotation sits over a <strong>frozen frame</strong> of the viewport, so the agent sees the exact page state you reacted to.</p><h3 id="narrate-by-voice" tabindex="-1">Narrate by voice <a class="header-anchor" href="#narrate-by-voice" aria-label="Permalink to &quot;Narrate by voice&quot;">​</a></h3><p>Speak instead of typing. The mic stays available while agents run, so you can queue the next change without waiting. Voice + drawing work together.</p><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h2><p>Official table:</p><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Toggle Design Mode</td><td><code>Cmd+Shift+D</code></td></tr><tr><td>Select an area</td><td><code>Shift+drag</code></td></tr><tr><td>Add element to chat</td><td><code>Cmd+L</code></td></tr><tr><td>Add element to input</td><td><code>Option+click</code></td></tr></tbody></table><h2 id="what-the-agent-sees" tabindex="-1">What the agent sees <a class="header-anchor" href="#what-the-agent-sees" aria-label="Permalink to &quot;What the agent sees&quot;">​</a></h2><p>Picking an element adds two complementary signals:</p><table tabindex="0"><thead><tr><th>Signal</th><th>Contents</th><th>Why</th></tr></thead><tbody><tr><td><strong>Element identity</strong></td><td>xpath, component, attributes, computed styles, props from the <strong>fiber tree</strong></td><td>Find the source and edit the right file</td></tr><tr><td><strong>A screenshot</strong></td><td>layout, surrounding elements, exact page state</td><td>Spatial context</td></tr></tbody></table><p>Do not invent extra signals (full DOM dumps, network HAR, design tokens) unless a later official page lists them.</p><h2 id="work-in-flow" tabindex="-1">Work in flow <a class="header-anchor" href="#work-in-flow" aria-label="Permalink to &quot;Work in flow&quot;">​</a></h2><p>One UI edit usually leads to the next. Point at one element, describe the change, move to another part of the page, and send another edit <strong>before the first one finishes</strong>. As agents finish, the app hot-reloads.</p><p>This is how you run several <strong>subagents</strong> at once on an interface.</p><p>The iOS app can also enter Design Mode (point, click, and draw on images or front-end components). That lives on <a href="https://cursor.com/docs/cloud-agent/mobile" target="_blank" rel="noreferrer">Cursor for iOS</a> — this page stays on the desktop Agents Window.</p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><ul><li>Spacing, alignment, and “make this match that” on a running page</li><li>Crowded or animated regions you can circle faster than you can describe</li><li>Hands-busy iteration: voice while the previous agent is still running</li></ul><p>Stay in ordinary Agent chat when the change is not visual (API contract, data model). Use <a href="./../claude/claude-design.html">Claude Design</a> when you need a <strong>standalone</strong> brand-aware canvas and a handoff bundle, not an in-editor overlay.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pitfall</th><th>Do this</th></tr></thead><tbody><tr><td>Describe a pixel change in prose only</td><td>Select the element or draw the region</td></tr><tr><td>Forget it lives in the Agents Window <strong>browser</strong></td><td>Open that browser, then <code>Cmd+Shift+D</code></td></tr><tr><td>Pick a slow / weak-at-UI model</td><td>Official: <strong>Composer 2.5</strong></td></tr><tr><td>Assume drawing tracks a live animation</td><td>Annotation is on a <strong>frozen</strong> viewport frame</td></tr><tr><td>Confuse this with Claude Design</td><td>Claude Design is a separate web canvas; this is visual prompting <strong>on your running app</strong></td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./cursor.html">Cursor tutorial</a> — Agent / Ask / Plan / Debug in the editor</li><li><a href="./cloud-agents.html">Cloud Agents</a> — same family, isolated VM</li><li>Official: <a href="https://cursor.com/docs/agent/design-mode" target="_blank" rel="noreferrer">Design Mode</a>, <a href="https://cursor.com/docs/agent/agents-window" target="_blank" rel="noreferrer">Agents Window</a>, <a href="https://cursor.com/docs/agent/tools/browser" target="_blank" rel="noreferrer">Browser</a></li></ul>',42)])])}const b=t(r,[["render",i]]);export{f as __pageData,b as default};
